import{_ as e,o as s,c as t,a2 as l}from"./chunks/framework.CWWEQfK7.js";const n=JSON.parse('{"title":"耳鼠 Ershu","description":"面向企业私有代码的自托管项目上下文服务，把多个仓库整理成可搜索、可追溯、供人和 AI 共同使用的项目知识。","frontmatter":{"page_id":"home","layout":"home","title":"耳鼠 Ershu","description":"面向企业私有代码的自托管项目上下文服务，把多个仓库整理成可搜索、可追溯、供人和 AI 共同使用的项目知识。","hero":{"name":"耳鼠 Ershu","text":"让复杂项目拥有一份人和 AI 共用的记忆","tagline":"把前端、后端和微服务等多个私有仓库，整理成可搜索、可追溯、能够持续更新的项目上下文。团队通过网页理解项目，AI 通过 MCP 读取同一份事实。","image":{"src":"/favicon.ico","alt":"耳鼠 Ershu 标志"},"actions":[{"theme":"brand","text":"从零完成一次分析","link":"/guide/quick-start"},{"theme":"alt","text":"看看 Ershu 是否适合你","link":"#适合什么样的项目"}]},"features":[{"title":"跨仓库理解整个项目","details":"把前端、后端、微服务和共享库放进同一个项目视图，减少在不同仓库之间来回拼接上下文。"},{"title":"从答案回到源码","details":"文档、搜索结果和问答引用保留来源位置，结论可以继续回到当前代码核对。"},{"title":"人和 AI 使用同一份事实","details":"团队成员通过网页阅读，开发智能体通过 MCP 查询同一项目的文档、结构和检索结果。"},{"title":"让项目知识跟着代码更新","details":"先建立覆盖全部仓库的项目基线，再按后续提交刷新事实、关系和搜索索引。"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1786289447000}'),r={name:"index.md"};function i(c,a,h,o,d,p){return s(),t("div",null,[...a[0]||(a[0]=[l('<h2 id="真正难读懂的-往往不是一段代码" tabindex="-1">真正难读懂的，往往不是一段代码 <a class="header-anchor" href="#真正难读懂的-往往不是一段代码" aria-label="Permalink to &quot;真正难读懂的，往往不是一段代码&quot;">​</a></h2><p>复杂项目的问题通常藏在仓库之间：一个页面调用哪个接口，一个接口又依赖哪个服务，某项配置为什么会改变整条流程。新人反复搜索，维护者重复解释，开发智能体每次也要重新建立上下文。</p><div class="home-card-grid home-card-grid--three"><article class="home-card"><p class="home-card-label">接手陌生项目</p><h3>先找到入口、边界和关键流程</h3><p>从项目文档、仓库树、搜索和代码关系开始理解，不必先猜应该打开哪个仓库、询问哪位维护者。</p></article><article class="home-card"><p class="home-card-label">梳理遗留系统</p><h3>从当前代码重新整理项目知识</h3><p>当旧文档缺失或已经过期时，按当前提交生成可以继续回到源码核对的结构、说明和关系。</p></article><article class="home-card"><p class="home-card-label">开展 AI 编程</p><h3>给智能体项目上下文，而不只是一个目录</h3><p>让智能体按权限查询已经整理的项目事实，减少重复扫描和与当前任务无关的代码输入。</p></article></div><aside class="home-statement"><p class="home-statement-label">为开发智能体准备可靠上下文</p><p class="home-statement-title">不是把更多代码塞给 AI，而是让它按需拿到相关、版本明确、能够核对的项目上下文。</p><p>Ershu 把项目文档、代码搜索、关系和来源位置作为可复用结果提供给网页、API 与 MCP。它有助于减少重复读取和无关上下文；实际 Token 消耗取决于项目、任务和模型，应通过真实工作负载验证。</p></aside><h2 id="为企业私有代码场景设计" tabindex="-1">为企业私有代码场景设计 <a class="header-anchor" href="#为企业私有代码场景设计" aria-label="Permalink to &quot;为企业私有代码场景设计&quot;">​</a></h2><p>私有化部署的价值不只在于“服务装在哪里”，还在于企业能否决定谁可以访问哪些项目、代码通过什么方式读取，以及使用哪个模型服务。</p><div class="home-card-grid home-card-grid--four"><article class="home-card home-card--compact"><p class="home-card-label">自行部署</p><h3>数据边界由部署方式决定</h3><p>服务、仓库凭据和存储由使用方管理，可以部署在自己的基础设施中。</p></article><article class="home-card home-card--compact"><p class="home-card-label">只读分析</p><h3>理解代码，不执行仓库脚本</h3><p>Worker 使用受限的只读工作区工具提取项目事实，并限制路径、文件大小和调用预算。</p></article><article class="home-card home-card--compact"><p class="home-card-label">权限边界</p><h3>成员和智能体分别授权</h3><p>网页访问受项目成员权限约束，MCP 密钥还可以限制项目和工具范围。</p></article><article class="home-card home-card--compact"><p class="home-card-label">模型选择</p><h3>按环境配置模型通道</h3><p>管理员分别配置大语言模型、嵌入和重排通道，不把模型密钥写进前端。</p></article></div><p class="home-note">自行部署为企业提供了控制数据边界的起点。代码是否离开内网，仍取决于你配置的模型服务、网络和日志策略。</p><h2 id="适合什么样的项目" tabindex="-1">适合什么样的项目？ <a class="header-anchor" href="#适合什么样的项目" aria-label="Permalink to &quot;适合什么样的项目？&quot;">​</a></h2><div class="home-fit-grid"><div class="home-fit-item"><span class="home-fit-index">01</span><div><h3>由多个仓库共同交付一个产品</h3><p>前端、后端、微服务、共享库和基础设施分散维护，但理解功能时需要把它们放回同一个项目。</p></div></div><div class="home-fit-item"><span class="home-fit-index">02</span><div><h3>需要接手陌生或历史代码</h3><p>项目缺少可靠文档，关键知识掌握在少数人手中，团队需要从当前源码重新建立共同认识。</p></div></div><div class="home-fit-item"><span class="home-fit-index">03</span><div><h3>正在让开发者和 AI 协作</h3><p>希望智能体获得受权限控制、可以追溯来源的项目上下文，而不是每次从零读取全部仓库。</p></div></div></div><h2 id="从你现在的问题开始" tabindex="-1">从你现在的问题开始 <a class="header-anchor" href="#从你现在的问题开始" aria-label="Permalink to &quot;从你现在的问题开始&quot;">​</a></h2><div class="home-path-grid"><a class="home-path-card" href="/overview/what-is-ershu"><span>判断是否适合</span><strong>了解 Ershu 的能力与边界</strong><small>先确认它能解决什么，以及当前不承诺什么。</small></a><a class="home-path-card" href="/configuration/"><span>准备自行部署</span><strong>配置服务、权限和安全边界</strong><small>从基础设置进入五个模块的完整配置说明。</small></a><a class="home-path-card" href="/guide/quick-start"><span>开始真实验证</span><strong>完成第一次完整项目分析</strong><small>按照可检查的结果，从启动服务走到生成项目知识。</small></a><a class="home-path-card" href="/development/"><span>参与项目开发</span><strong>理解架构、边界和扩展方式</strong><small>查看五个模块怎样协作，以及如何安全地增加能力。</small></a></div><section class="home-final-cta"><p class="home-card-label">从一个真实项目开始</p><h2>先让 Ershu 回答一个你已经厌倦重复解释的问题</h2><p>选择一个真正需要跨仓库理解的项目，建立完整基线，再检查生成的文档、搜索结果和引用是否能够带你回到正确源码。</p><div class="home-final-actions"><a class="VPButton medium brand" href="/guide/quick-start">开始第一次分析</a><a class="VPButton medium alt" href="/overview/what-is-ershu">继续了解 Ershu</a></div></section><blockquote><p>本站内容按当前源码、配置、类型和测试核对，并与 Ershu MCP 线上文档交叉验证。</p></blockquote>',14)])])}const u=e(r,[["render",i]]);export{n as __pageData,u as default};
